import { TableSkeleton } from '../../components/ui/Skeleton';
import { useState, useMemo, useRef } from 'react'
import { deleteItemSmart } from '../../lib/contentApi'
import { useRealtimeCollection } from '../../lib/useRealtimeCollection'
import { addDocument, updateDocument, uploadFile } from '../../lib/firebaseHelpers'
import toast from 'react-hot-toast'
import Modal from '../../components/Modal'
import ExportButton from '../../components/ExportButton'

const DEFAULT_CATEGORIES = ['Campus', 'Labs', 'Events', 'Facilities', 'Students']

const emptyForm = { title: '', category: 'Campus', event: '', imageUrl: '', order: 0 }

export default function ManageGallery() {
  const { data: images, loading } = useRealtimeCollection('gallery')
  const [modal, setModal] = useState(false)
  const [editing, setEditing] = useState(null)
  const [form, setForm] = useState(emptyForm)
  const [preview, setPreview] = useState('')
  const [uploading, setUploading] = useState(false)
  const [bulkMode, setBulkMode] = useState(false)
  const [bulkProgress, setBulkProgress] = useState(null) // {done, total}
  const [filterCat, setFilterCat] = useState('all')
  const [filterEvent, setFilterEvent] = useState('all')
  const [customCats, setCustomCats] = useState(() => {
    try { return JSON.parse(localStorage.getItem('gallery_custom_cats') || '[]'); } catch { return []; }
  })
  const [newCatInput, setNewCatInput] = useState('')
  const dragSrc = useRef(null)

  const allCategories = useMemo(() => {
    const set = new Set([...DEFAULT_CATEGORIES, ...customCats, ...images.map(i => i.category).filter(Boolean)])
    return Array.from(set)
  }, [customCats, images])

  const events = useMemo(() => {
    const set = new Set(images.map(i => i.event).filter(Boolean))
    return Array.from(set).sort()
  }, [images])

  const filtered = useMemo(() => {
    return images
      .filter(i => filterCat === 'all' || i.category === filterCat)
      .filter(i => filterEvent === 'all' || (i.event || '') === filterEvent)
      .sort((a, b) => (a.order || 0) - (b.order || 0))
  }, [images, filterCat, filterEvent])

  // Group by event when event filter is 'all' but a category bundle is open
  const eventBuckets = useMemo(() => {
    const map = new Map()
    filtered.forEach(img => {
      const key = img.event || '(No event)'
      if (!map.has(key)) map.set(key, [])
      map.get(key).push(img)
    })
    return Array.from(map.entries())
  }, [filtered])

  const addCustomCat = () => {
    const v = newCatInput.trim()
    if (!v) return
    if (allCategories.includes(v)) { toast.error('Already exists'); return }
    const next = [...customCats, v]
    setCustomCats(next)
    localStorage.setItem('gallery_custom_cats', JSON.stringify(next))
    setNewCatInput('')
    toast.success(`Added "${v}"`)
  }

  const handleSingleUpload = async (e) => {
    const file = e.target.files?.[0]
    if (!file) return
    if (!file.type.startsWith('image/')) { toast.error('Images only'); return }
    if (file.size > 5 * 1024 * 1024) { toast.error('Max 5MB'); return }
    setUploading(true)
    try {
      const path = `public/gallery/${Date.now()}_${file.name.replace(/\s+/g, '_')}`
      const url = await uploadFile(path, file)
      setForm({ ...form, imageUrl: url })
      setPreview(url)
      toast.success('Uploaded')
    } catch (err) { toast.error(err.message) }
    finally { setUploading(false); e.target.value = '' }
  }

  const handleBulkUpload = async (e) => {
    const files = Array.from(e.target.files || [])
    if (!files.length) return
    if (!form.category) { toast.error('Pick a category first'); return }
    setBulkProgress({ done: 0, total: files.length })
    const baseOrder = (images.filter(i => i.category === form.category).length) || 0
    for (let i = 0; i < files.length; i++) {
      const file = files[i]
      if (!file.type.startsWith('image/')) continue
      if (file.size > 5 * 1024 * 1024) { toast.error(`${file.name} too big`); continue }
      try {
        const path = `public/gallery/${Date.now()}_${i}_${file.name.replace(/\s+/g, '_')}`
        const url = await uploadFile(path, file)
        await addDocument('gallery', {
          title: file.name.replace(/\.[^.]+$/, ''),
          category: form.category,
          event: form.event || '',
          imageUrl: url,
          order: baseOrder + i,
        })
      } catch (err) { console.error(file.name, err) }
      setBulkProgress({ done: i + 1, total: files.length })
    }
    toast.success(`Bulk uploaded ${files.length} images to ${form.category}`)
    setBulkProgress(null)
    setBulkMode(false)
    closeModal()
    e.target.value = ''
  }

  const save = async () => {
    if (!form.imageUrl) { toast.error('Upload or paste URL'); return }
    try {
      if (editing) {
        await updateDocument('gallery', editing.id, form)
        toast.success('Updated')
      } else {
        await addDocument('gallery', { ...form, order: form.order || images.length })
        toast.success('Added')
      }
      closeModal()
    } catch (err) { toast.error(err.message) }
  }

  const remove = async (id) => {
    if (!confirm('Delete?')) return
    try { await deleteItemSmart('gallery', id); toast.success('Deleted') }
    catch (err) { toast.error(err.message) }
  }

  const openEdit = (img) => {
    setEditing(img)
    setForm({ title: img.title || '', category: img.category || 'Campus', event: img.event || '', imageUrl: img.imageUrl, order: img.order || 0 })
    setPreview(img.imageUrl)
    setBulkMode(false)
    setModal(true)
  }

  const openCreate = () => { setEditing(null); setForm(emptyForm); setPreview(''); setBulkMode(false); setModal(true) }
  const openBulk = () => { setEditing(null); setForm(emptyForm); setBulkMode(true); setModal(true) }
  const closeModal = () => { setModal(false); setEditing(null); setForm(emptyForm); setPreview(''); setBulkMode(false); setBulkProgress(null) }

  // Drag-and-drop reordering within current view
  const onDragStart = (img) => () => { dragSrc.current = img.id }
  const onDragOver = (e) => { e.preventDefault() }
  const onDrop = (target) => async (e) => {
    e.preventDefault()
    const srcId = dragSrc.current
    if (!srcId || srcId === target.id) return
    const src = images.find(i => i.id === srcId)
    if (!src) return
    try {
      await updateDocument('gallery', src.id, { order: target.order || 0 })
      await updateDocument('gallery', target.id, { order: (src.order || 0) + 0.5 })
      toast.success('Reordered')
    } catch (err) { toast.error(err.message) }
    dragSrc.current = null
  }

  return (
    <div>
      <div className="flex items-center justify-between mb-6 flex-wrap gap-3">
        <div>
          <h1 className="text-2xl font-bold text-white">Manage Gallery</h1>
          <p className="text-sm text-slate-400">{images.length} images ┬╖ {events.length} events</p>
        </div>
        <div className="flex gap-2">
          <ExportButton data={images} filename="gallery" columns={[
            { key: 'title', label: 'Title' },
            { key: 'category', label: 'Category' },
            { key: 'event', label: 'Event' },
            { key: 'imageUrl', label: 'Image URL' },
            { key: 'order', label: 'Order' },
          ]} />
          <button onClick={openBulk} className="bg-blue-500/20 hover:bg-blue-500/30 text-blue-300 text-sm font-bold px-4 py-2 rounded-lg">≡ƒôª Bulk Upload</button>
          <button onClick={openCreate} className="btn-primary">+ Add Image</button>
        </div>
      </div>

      {/* Category filter chips */}
      <div className="mb-3">
        <div className="text-xs text-slate-500 uppercase font-bold mb-2">Category</div>
        <div className="flex flex-wrap gap-2 items-center">
          <button onClick={() => setFilterCat('all')}
            className={`px-3 py-1.5 rounded-full text-xs font-medium ${filterCat === 'all' ? 'bg-green-brand text-white' : 'bg-white/5 text-slate-300 border border-white/10'}`}>
            All ({images.length})
          </button>
          {allCategories.map(c => {
            const n = images.filter(i => i.category === c).length
            return (
              <button key={c} onClick={() => setFilterCat(c)}
                className={`px-3 py-1.5 rounded-full text-xs font-medium ${filterCat === c ? 'bg-green-brand text-white' : 'bg-white/5 text-slate-300 border border-white/10'}`}>
                {c} ({n})
              </button>
            )
          })}
          <div className="flex items-center gap-1 bg-white/5 border border-dashed border-white/20 rounded-full pl-2 pr-1 py-0.5">
            <input value={newCatInput} onChange={e => setNewCatInput(e.target.value)}
              onKeyDown={e => e.key === 'Enter' && addCustomCat()}
              placeholder="+ custom"
              className="bg-transparent text-xs text-white outline-none w-20" />
            <button onClick={addCustomCat} className="text-xs bg-green-brand text-white rounded-full w-5 h-5 leading-none">+</button>
          </div>
        </div>
      </div>

      {/* Event filter chips */}
      {events.length > 0 && (
        <div className="mb-6">
          <div className="text-xs text-slate-500 uppercase font-bold mb-2">Event</div>
          <div className="flex flex-wrap gap-2">
            <button onClick={() => setFilterEvent('all')}
              className={`px-3 py-1.5 rounded-full text-xs font-medium ${filterEvent === 'all' ? 'bg-blue-500 text-white' : 'bg-white/5 text-slate-300 border border-white/10'}`}>
              All events
            </button>
            {events.map(ev => (
              <button key={ev} onClick={() => setFilterEvent(ev)}
                className={`px-3 py-1.5 rounded-full text-xs font-medium ${filterEvent === ev ? 'bg-blue-500 text-white' : 'bg-white/5 text-slate-300 border border-white/10'}`}>
                {ev}
              </button>
            ))}
          </div>
        </div>
      )}

      {loading && <TableSkeleton />}

      {!loading && filtered.length === 0 && (
        <div className="bg-white/5 border border-white/10 rounded-2xl p-12 text-center">
          <p className="text-slate-400">No images in this view.</p>
        </div>
      )}

      {/* Bundled by event */}
      {filterEvent === 'all' && eventBuckets.length > 1 ? (
        <div className="space-y-8">
          {eventBuckets.map(([eventName, imgs]) => (
            <div key={eventName}>
              <div className="flex items-baseline justify-between mb-3">
                <h2 className="text-lg font-bold text-white">{eventName}</h2>
                <span className="text-xs text-slate-500">{imgs.length} images</span>
              </div>
              <div className="grid sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
                {imgs.map(img => <ImageCard key={img.id} img={img} openEdit={openEdit} remove={remove}
                  onDragStart={onDragStart(img)} onDragOver={onDragOver} onDrop={onDrop(img)} />)}
              </div>
            </div>
          ))}
        </div>
      ) : (
        <div className="grid sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4">
          {filtered.map(img => <ImageCard key={img.id} img={img} openEdit={openEdit} remove={remove}
            onDragStart={onDragStart(img)} onDragOver={onDragOver} onDrop={onDrop(img)} />)}
        </div>
      )}

      <Modal isOpen={modal} onClose={closeModal} title={bulkMode ? 'Bulk Upload' : (editing ? 'Edit Image' : 'Add Image')}>
        <div className="space-y-4">
          {bulkMode ? (
            <>
              <div className="bg-blue-500/10 border border-blue-500/30 rounded-lg p-3 text-xs text-blue-200">
                <div className="font-bold mb-1">≡ƒôª Bulk Upload Mode</div>
                <div>Pick category + event, then select many images. All go to one folder at once.</div>
              </div>
              <div>
                <label className="text-sm font-medium text-slate-300 mb-1 block">Category *</label>
                <select className="input-field" value={form.category} onChange={e => setForm({ ...form, category: e.target.value })}>
                  {allCategories.map(c => <option key={c}>{c}</option>)}
                </select>
              </div>
              <div>
                <label className="text-sm font-medium text-slate-300 mb-1 block">Event name (optional, groups bundle)</label>
                <input className="input-field" value={form.event} onChange={e => setForm({ ...form, event: e.target.value })}
                  placeholder="e.g. Annual Day 2026" list="events-list" />
                <datalist id="events-list">
                  {events.map(ev => <option key={ev} value={ev} />)}
                </datalist>
              </div>
              <label className="border-2 border-dashed border-slate-600 rounded-xl p-8 text-center cursor-pointer hover:border-green-brand block">
                {bulkProgress ? (
                  <div>
                    <div className="text-green-brand font-bold mb-2">Uploading {bulkProgress.done}/{bulkProgress.total}</div>
                    <div className="w-full bg-white/10 rounded-full h-2">
                      <div className="bg-green-brand h-2 rounded-full transition-all" style={{ width: `${(bulkProgress.done / bulkProgress.total) * 100}%` }} />
                    </div>
                  </div>
                ) : (
                  <>
                    <div className="text-4xl mb-2">≡ƒô╖</div>
                    <p className="text-sm text-white font-medium">Select multiple images</p>
                    <p className="text-xs text-slate-500 mt-1">JPG/PNG ┬╖ 5MB each</p>
                  </>
                )}
                <input type="file" accept="image/*" multiple className="hidden" onChange={handleBulkUpload} disabled={!!bulkProgress} />
              </label>
            </>
          ) : (
            <>
              <div><label className="text-sm font-medium text-slate-300 mb-1 block">Title</label>
                <input className="input-field" value={form.title} onChange={e => setForm({ ...form, title: e.target.value })} /></div>
              <div className="grid grid-cols-2 gap-3">
                <div>
                  <label className="text-sm font-medium text-slate-300 mb-1 block">Category</label>
                  <select className="input-field" value={form.category} onChange={e => setForm({ ...form, category: e.target.value })}>
                    {allCategories.map(c => <option key={c}>{c}</option>)}
                  </select>
                </div>
                <div>
                  <label className="text-sm font-medium text-slate-300 mb-1 block">Event (optional)</label>
                  <input className="input-field" value={form.event} onChange={e => setForm({ ...form, event: e.target.value })}
                    placeholder="e.g. Annual Day" list="events-list-single" />
                  <datalist id="events-list-single">
                    {events.map(ev => <option key={ev} value={ev} />)}
                  </datalist>
                </div>
              </div>
              <div>
                <label className="text-sm font-medium text-slate-300 mb-1 block">Upload Image</label>
                <label className="border-2 border-dashed border-slate-600 rounded-xl p-4 text-center cursor-pointer hover:border-green-brand transition-colors block">
                  {preview ? (
                    <img src={preview} alt="Preview" className="w-full max-h-40 object-contain mx-auto rounded-lg" />
                  ) : (
                    <p className="text-sm text-slate-400">{uploading ? 'Uploading...' : 'Click to select image (max 5MB)'}</p>
                  )}
                  <input type="file" accept="image/*" className="hidden" onChange={handleSingleUpload} disabled={uploading} />
                </label>
              </div>
              <div className="relative flex items-center py-1">
                <div className="flex-grow border-t border-slate-700"></div>
                <span className="flex-shrink-0 mx-3 text-slate-500 text-xs">or paste URL</span>
                <div className="flex-grow border-t border-slate-700"></div>
              </div>
              <input className="input-field" value={form.imageUrl}
                onChange={e => { setForm({ ...form, imageUrl: e.target.value }); setPreview(e.target.value); }}
                placeholder="https://..." />
              <button onClick={save} disabled={uploading} className="btn-primary w-full disabled:opacity-50">{editing ? 'Update' : 'Add'} Image</button>
            </>
          )}
        </div>
      </Modal>
    </div>
  )
}

function ImageCard({ img, openEdit, remove, onDragStart, onDragOver, onDrop }) {
  return (
    <div
      draggable
      onDragStart={onDragStart}
      onDragOver={onDragOver}
      onDrop={onDrop}
      className="bg-[#111111] rounded-2xl border border-slate-800 overflow-hidden group hover:border-green-brand/30 transition-all cursor-move"
    >
      <div className="aspect-video relative">
        <img src={img.imageUrl} alt={img.title} className="w-full h-full object-cover" loading="lazy" />
        <div className="absolute inset-0 bg-black/60 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center gap-3">
          <button onClick={() => openEdit(img)} className="text-sm bg-blue-600 hover:bg-blue-500 text-white px-3 py-1.5 rounded-lg">Edit</button>
          <button onClick={() => remove(img.id)} className="text-sm bg-red-600 hover:bg-red-500 text-white px-3 py-1.5 rounded-lg">Delete</button>
        </div>
        <div className="absolute top-2 left-2 text-[10px] bg-black/60 text-white/60 px-1.5 py-0.5 rounded">Γï«Γï« drag</div>
      </div>
      <div className="p-3">
        <p className="text-sm font-medium text-white truncate">{img.title || '(untitled)'}</p>
        <div className="flex gap-1 mt-1 flex-wrap">
          <span className="badge badge-green text-[10px]">{img.category}</span>
          {img.event && <span className="badge badge-navy text-[10px]">{img.event}</span>}
        </div>
      </div>
    </div>
  )
}

import { TableSkeleton } from '../../components/ui/Skeleton';
import { useState, useMemo } from 'react'
import { useRealtimeCollection } from '../../lib/useRealtimeCollection'
import { addDocument, updateDocument, deleteDocument } from '../../lib/firebaseHelpers'
import { formatCurrency, generateInvoiceNumber } from '../../lib/invoice'
import InvoiceView from '../../components/InvoiceView'
import toast from 'react-hot-toast'
import Modal from '../../components/Modal'
import ExportButton from '../../components/ExportButton'

const emptyForm = { studentUid: '', studentName: '', studentEmail: '', courseName: '', description: '', amount: '', dueDate: '' }

export default function ManageInvoices() {
  const { data: invoices, loading } = useRealtimeCollection('invoices', { fallback: [] })
  const { data: students } = useRealtimeCollection('students', { fallback: [] })
  const [modal, setModal] = useState(false)
  const [form, setForm] = useState(emptyForm)
  const [sending, setSending] = useState(false)
  const [search, setSearch] = useState('')
  const [dropdownOpen, setDropdownOpen] = useState(false)
  const [viewInvoice, setViewInvoice] = useState(null)
  const [filterStudent, setFilterStudent] = useState('all')
  const [filterStatus, setFilterStatus] = useState('all')

  const filteredStudents = useMemo(() => {
    if (!search) return students
    const q = search.toLowerCase()
    return students.filter(s => (s.name || '').toLowerCase().includes(q) || (s.email || '').toLowerCase().includes(q) || (s.studentId || '').toLowerCase().includes(q))
  }, [students, search])

  // Group invoices by student
  const groups = useMemo(() => {
    const map = new Map()
    invoices.forEach(inv => {
      const key = inv.studentUid || inv.studentEmail || 'unknown'
      if (!map.has(key)) map.set(key, { uid: key, name: inv.studentName, email: inv.studentEmail, items: [], total: 0, paid: 0, pending: 0 })
      const g = map.get(key)
      g.items.push(inv)
      g.total += Number(inv.amount) || 0
      if (inv.status === 'paid') g.paid += Number(inv.amount) || 0
      if (inv.status === 'pending') g.pending += Number(inv.amount) || 0
    })
    return Array.from(map.values()).sort((a, b) => b.pending - a.pending)
  }, [invoices])

  const visibleGroups = useMemo(() => {
    let g = groups
    if (filterStudent !== 'all') g = g.filter(x => x.uid === filterStudent)
    if (filterStatus !== 'all') {
      g = g.map(x => ({ ...x, items: x.items.filter(i => i.status === filterStatus) })).filter(x => x.items.length)
    }
    return g
  }, [groups, filterStudent, filterStatus])

  const createInvoice = async () => {
    if (!form.studentUid || !form.courseName || !form.amount) { toast.error('Student, course and amount required'); return }
    setSending(true)
    const num = generateInvoiceNumber(invoices.length)
    const paidAt = new Date().toLocaleDateString('en-IN', { day: '2-digit', month: 'short', year: 'numeric' })
    let invoiceOk = false
    try {
      await addDocument('invoices', {
        invoiceNumber: num,
        studentUid: form.studentUid,
        studentName: form.studentName,
        studentEmail: form.studentEmail,
        courseName: form.courseName,
        description: form.description,
        amount: Number(form.amount),
        dueDate: form.dueDate,
        status: 'pending',
        paidAt: '',
        issuedDate: paidAt,
      })
      invoiceOk = true
    } catch (err) {
      console.error('[invoice create]', err)
      toast.error('Invoice failed: ' + (err.message || err.code || 'unknown'))
      setSending(false)
      return
    }
    // Notify student ΓÇö non-fatal; invoice already saved
    try {
      await addDocument('notifications', {
        studentUid: form.studentUid,
        studentName: form.studentName,
        studentEmail: form.studentEmail,
        subject: `New Invoice ${num}`,
        message: `${form.courseName} ΓÇö ${formatCurrency(Number(form.amount))}${form.dueDate ? ` ┬╖ due ${form.dueDate}` : ''}. View in My Invoices.`,
        audience: 'invoice',
        read: false,
      })
      toast.success(`Invoice ${num} created + student notified`)
    } catch (err) {
      console.error('[invoice notify]', err)
      toast.success(`Invoice ${num} created (notification failed ΓÇö student can still see invoice)`)
    }
    if (invoiceOk) closeModal()
    setSending(false)
  }

  const markPaid = async (inv) => {
    const paidAt = new Date().toLocaleDateString('en-IN', { day: '2-digit', month: 'short', year: 'numeric' })
    try {
      await updateDocument('invoices', inv.id, { status: 'paid', paidAt })
    } catch (err) {
      console.error('[markPaid]', err)
      toast.error('Mark paid failed: ' + (err.message || err.code))
      return
    }
    try {
      await addDocument('notifications', {
        studentUid: inv.studentUid,
        studentName: inv.studentName,
        studentEmail: inv.studentEmail,
        subject: `Invoice ${inv.invoiceNumber} marked paid`,
        message: `Payment received for ${inv.courseName} ΓÇö ${formatCurrency(inv.amount)}.`,
        audience: 'invoice',
        read: false,
      })
      toast.success('Marked paid + student notified')
    } catch (err) {
      console.error('[markPaid notify]', err)
      toast.success('Marked paid (notification failed)')
    }
  }

  const resend = async (inv) => {
    try {
      await addDocument('notifications', {
        studentUid: inv.studentUid,
        studentName: inv.studentName,
        studentEmail: inv.studentEmail,
        subject: `Reminder: Invoice ${inv.invoiceNumber}`,
        message: `${inv.courseName} ΓÇö ${formatCurrency(inv.amount)}${inv.dueDate ? ` ┬╖ due ${inv.dueDate}` : ''}. Please complete payment.`,
        audience: 'invoice',
        read: false,
      })
      toast.success('Reminder sent')
    } catch (err) {
      console.error('[resend]', err)
      toast.error('Reminder failed: ' + (err.message || err.code))
    }
  }

  const remove = async (id) => {
    if (!confirm('Delete invoice?')) return
    try { await deleteDocument('invoices', id); toast.success('Deleted') }
    catch (err) { toast.error(err.message) }
  }

  const closeModal = () => { setModal(false); setForm(emptyForm); setSearch(''); setDropdownOpen(false) }

  const openView = (inv) => {
    setViewInvoice({
      invoiceNumber: inv.invoiceNumber,
      date: inv.issuedDate || inv.paidAt || 'ΓÇö',
      studentName: inv.studentName,
      studentEmail: inv.studentEmail,
      courseTitle: inv.courseName,
      description: inv.description,
      amount: inv.amount,
      transactionId: inv.id,
      paymentMethod: 'Invoice (manual)',
      status: inv.status === 'paid' ? 'Paid' : 'Pending',
    })
  }

  const statusColors = { pending: 'badge-gold', paid: 'badge-green', overdue: 'badge-red' }
  const totalRevenue = invoices.filter(i => i.status === 'paid').reduce((s, i) => s + (i.amount || 0), 0)
  const totalPending = invoices.filter(i => i.status === 'pending').reduce((s, i) => s + (i.amount || 0), 0)

  return (
    <div>
      <div className="flex items-center justify-between mb-6 flex-wrap gap-3">
        <div>
          <h1 className="text-2xl font-bold text-white">Manage Invoices</h1>
          <p className="text-sm text-slate-400">{invoices.length} invoices ┬╖ {groups.length} student{groups.length !== 1 ? 's' : ''}</p>
        </div>
        <div className="flex gap-2">
          <ExportButton data={invoices} filename="invoices" columns={[
            { key: 'invoiceNumber', label: 'Invoice #' },
            { key: 'studentName', label: 'Student' },
            { key: 'studentEmail', label: 'Email' },
            { key: 'courseName', label: 'Course' },
            { key: 'description', label: 'Description' },
            { key: 'amount', label: 'Amount (Γé╣)' },
            { key: 'status', label: 'Status' },
            { key: 'issuedDate', label: 'Issued' },
            { key: 'dueDate', label: 'Due Date' },
            { key: 'paidAt', label: 'Paid At' },
          ]} />
          <button onClick={() => setModal(true)} className="btn-primary">+ Create Invoice</button>
        </div>
      </div>
      {loading && <TableSkeleton />}

      {/* Stats */}
      <div className="grid grid-cols-2 sm:grid-cols-4 gap-4 mb-6">
        <div className="bg-[#111111] rounded-2xl p-4 border border-slate-800">
          <p className="text-xs text-slate-400 mb-1">Pending</p>
          <p className="text-xl font-bold text-amber-500">{invoices.filter(i => i.status === 'pending').length}</p>
        </div>
        <div className="bg-[#111111] rounded-2xl p-4 border border-slate-800">
          <p className="text-xs text-slate-400 mb-1">Paid</p>
          <p className="text-xl font-bold text-green-brand">{invoices.filter(i => i.status === 'paid').length}</p>
        </div>
        <div className="bg-[#111111] rounded-2xl p-4 border border-slate-800">
          <p className="text-xs text-slate-400 mb-1">Outstanding</p>
          <p className="text-xl font-bold text-amber-400">{formatCurrency(totalPending)}</p>
        </div>
        <div className="bg-[#111111] rounded-2xl p-4 border border-slate-800">
          <p className="text-xs text-slate-400 mb-1">Total Revenue</p>
          <p className="text-xl font-bold text-white">{formatCurrency(totalRevenue)}</p>
        </div>
      </div>

      {/* Filters */}
      <div className="flex gap-2 mb-4 flex-wrap">
        <select className="input-field w-auto" value={filterStudent} onChange={e => setFilterStudent(e.target.value)}>
          <option value="all">All students</option>
          {groups.map(g => <option key={g.uid} value={g.uid}>{g.name}</option>)}
        </select>
        <select className="input-field w-auto" value={filterStatus} onChange={e => setFilterStatus(e.target.value)}>
          <option value="all">All status</option>
          <option value="pending">Pending</option>
          <option value="paid">Paid</option>
        </select>
      </div>

      {/* Grouped list */}
      <div className="space-y-4">
        {visibleGroups.map(g => (
          <div key={g.uid} className="bg-[#111111] rounded-2xl border border-slate-800 overflow-hidden">
            <div className="p-4 flex items-center justify-between border-b border-slate-800 flex-wrap gap-2">
              <div>
                <div className="font-bold text-white">{g.name || '(no name)'}</div>
                <div className="text-xs text-slate-500">{g.email || g.uid}</div>
              </div>
              <div className="flex items-center gap-4 text-xs">
                <span className="text-slate-400">{g.items.length} invoice{g.items.length !== 1 ? 's' : ''}</span>
                {g.pending > 0 && <span className="badge badge-gold">Due {formatCurrency(g.pending)}</span>}
                {g.paid > 0 && <span className="badge badge-green">Paid {formatCurrency(g.paid)}</span>}
              </div>
            </div>
            <div className="table-container">
              <table>
                <thead>
                  <tr>
                    <th className="text-white">Invoice #</th>
                    <th className="text-white">Course</th>
                    <th className="text-white">Amount</th>
                    <th className="text-white">Due</th>
                    <th className="text-white">Status</th>
                    <th className="text-white">Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {g.items.map(inv => (
                    <tr key={inv.id}>
                      <td className="font-mono text-xs text-white">{inv.invoiceNumber}</td>
                      <td className="text-slate-300 text-sm">
                        <div>{inv.courseName}</div>
                        {inv.description && <div className="text-xs text-slate-500">{inv.description}</div>}
                      </td>
                      <td className="text-green-brand font-semibold">{formatCurrency(inv.amount)}</td>
                      <td className="text-slate-400 text-sm">{inv.dueDate || 'ΓÇö'}</td>
                      <td><span className={`badge ${statusColors[inv.status] || 'badge-navy'}`}>{inv.status}</span></td>
                      <td>
                        <div className="flex gap-2">
                          <button onClick={() => openView(inv)} className="text-xs text-blue-400 cursor-pointer">View</button>
                          {inv.status === 'pending' && (
                            <>
                              <button onClick={() => markPaid(inv)} className="text-xs text-green-brand font-bold cursor-pointer">Mark Paid</button>
                              <button onClick={() => resend(inv)} className="text-xs text-amber-400 cursor-pointer">Remind</button>
                            </>
                          )}
                          <button onClick={() => remove(inv.id)} className="text-xs text-red-400 cursor-pointer">Delete</button>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        ))}
        {!loading && visibleGroups.length === 0 && (
          <div className="bg-[#111111] rounded-2xl p-12 border border-slate-800 text-center">
            <p className="text-slate-400">No invoices yet. Click "Create Invoice" to bill a student.</p>
          </div>
        )}
      </div>

      {/* Create Invoice Modal */}
      <Modal isOpen={modal} onClose={closeModal} title="Create Invoice" size="lg">
        <div className="space-y-4">
          {/* Search + Dropdown */}
          <div className="relative">
            <label className="text-sm font-medium text-slate-300 mb-1 block">Select Student *</label>
            <div className="relative">
              <input
                className="input-field"
                placeholder="Search by name, email, or ID..."
                value={form.studentUid ? `${form.studentName} (${form.studentEmail || form.studentUid})` : search}
                onChange={e => {
                  setSearch(e.target.value)
                  setDropdownOpen(true)
                  if (!e.target.value) setForm({ ...form, studentUid: '', studentName: '', studentEmail: '' })
                }}
                onFocus={() => { if (!form.studentUid) setDropdownOpen(true) }}
              />
              {form.studentUid && (
                <button
                  onClick={() => { setForm({ ...form, studentUid: '', studentName: '', studentEmail: '' }); setSearch(''); setDropdownOpen(true) }}
                  className="absolute right-3 top-1/2 -translate-y-1/2 text-slate-400 hover:text-white cursor-pointer"
                >Γ£ò</button>
              )}
            </div>
            {dropdownOpen && !form.studentUid && filteredStudents.length > 0 && (
              <div className="absolute z-10 w-full mt-1 bg-[#111111] border border-slate-700 rounded-xl shadow-2xl max-h-48 overflow-y-auto">
                {filteredStudents.slice(0, 20).map(s => (
                  <button
                    key={s.id || s.uid}
                    onClick={() => {
                      setForm({ ...form, studentUid: s.id || s.uid, studentName: s.name, studentEmail: s.email || '' })
                      setSearch('')
                      setDropdownOpen(false)
                    }}
                    className="w-full text-left px-4 py-2.5 hover:bg-white/5 transition-colors flex items-center justify-between cursor-pointer"
                  >
                    <span className="text-white text-sm">{s.name}</span>
                    <span className="text-slate-500 text-xs">{s.email || s.studentId || s.id}</span>
                  </button>
                ))}
              </div>
            )}
          </div>

          <div><label className="text-sm font-medium text-slate-300 mb-1 block">Course / Service *</label><input className="input-field" value={form.courseName} onChange={e => setForm({ ...form, courseName: e.target.value })} placeholder="Physics Pro, NEET Batch 2026..." /></div>
          <div><label className="text-sm font-medium text-slate-300 mb-1 block">Description</label><textarea className="input-field resize-none" rows={2} value={form.description} onChange={e => setForm({ ...form, description: e.target.value })} placeholder="Monthly fees, course enrollment..." /></div>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <div><label className="text-sm font-medium text-slate-300 mb-1 block">Amount (INR) *</label><input type="number" className="input-field" value={form.amount} onChange={e => setForm({ ...form, amount: e.target.value })} placeholder="5000" /></div>
            <div><label className="text-sm font-medium text-slate-300 mb-1 block">Due Date</label><input type="date" className="input-field" value={form.dueDate} onChange={e => setForm({ ...form, dueDate: e.target.value })} /></div>
          </div>

          {/* Preview */}
          {form.studentUid && form.amount && (
            <div className="bg-blue-500/10 border border-blue-500/30 rounded-lg p-3 text-xs text-blue-200">
              Invoice <b>{formatCurrency(Number(form.amount) || 0)}</b> for <b>{form.studentName}</b>. Student receives notification + sees in My Invoices.
            </div>
          )}

          <button onClick={createInvoice} disabled={sending} className="btn-primary w-full disabled:opacity-50">{sending ? 'Creating...' : 'Create & Send Invoice'}</button>
        </div>
      </Modal>

      {/* View Invoice Modal (Payment-style) */}
      <Modal isOpen={!!viewInvoice} onClose={() => setViewInvoice(null)} title="Invoice Preview" size="lg">
        {viewInvoice && <InvoiceView invoice={viewInvoice} onClose={() => setViewInvoice(null)} />}
      </Modal>
    </div>
  )
}

