import { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { collection, query, where, getDocs, orderBy } from 'firebase/firestore';
import { db } from '../../lib/firebase';
import { useAuth } from '../../context/AuthContext';
import { formatCurrency } from '../../lib/invoice';
import { motion } from 'framer-motion';

export default function BasicPayment() {
  const { user } = useAuth();
  const [payments, setPayments] = useState([]);
  const [enrollments, setEnrollments] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!user?.uid) { setLoading(false); return; }
    let alive = true;

    (async () => {
      try {
        // Fetch payments for this user
        const payQ = query(
          collection(db, 'razorpayOrders'),
          where('uid', '==', user.uid),
        );
        const paySnap = await getDocs(payQ);
        const payData = paySnap.docs.map(d => ({ id: d.id, ...d.data() }));
        // Sort by createdAt desc (client-side to avoid index requirement)
        payData.sort((a, b) => {
          const aTime = a.createdAt?.toMillis?.() || 0;
          const bTime = b.createdAt?.toMillis?.() || 0;
          return bTime - aTime;
        });

        // Fetch enrollments for this user
        const enrolQ = query(
          collection(db, 'enrollments'),
          where('uid', '==', user.uid),
        );
        const enrolSnap = await getDocs(enrolQ);
        const enrolData = enrolSnap.docs.map(d => ({ id: d.id, ...d.data() }));

        if (alive) {
          setPayments(payData);
          setEnrollments(enrolData);
        }
      } catch (err) {
        console.error('[BasicPayment] fetch error:', err);
      } finally {
        if (alive) setLoading(false);
      }
    })();

    return () => { alive = false; };
  }, [user]);

  const statusBadge = (status) => {
    switch (status) {
      case 'paid':
        return <span className="inline-flex items-center gap-1 text-xs font-semibold bg-emerald-500/15 text-emerald-400 px-2.5 py-1 rounded-full">Γ£ô Paid</span>;
      case 'created':
        return <span className="inline-flex items-center gap-1 text-xs font-semibold bg-amber-500/15 text-amber-400 px-2.5 py-1 rounded-full">ΓÅ│ Pending</span>;
      case 'signature_mismatch':
        return <span className="inline-flex items-center gap-1 text-xs font-semibold bg-red-500/15 text-red-400 px-2.5 py-1 rounded-full">Γ£ò Failed</span>;
      default:
        return <span className="inline-flex items-center gap-1 text-xs font-semibold bg-slate-500/15 text-slate-400 px-2.5 py-1 rounded-full">{status || 'Unknown'}</span>;
    }
  };

  const formatDate = (ts) => {
    if (!ts) return 'ΓÇö';
    const d = ts.toDate ? ts.toDate() : new Date(ts);
    return d.toLocaleDateString('en-IN', { day: '2-digit', month: 'short', year: 'numeric' });
  };

  return (
    <div>
      <div className="flex items-center gap-3 mb-6">
        <div className="w-10 h-10 rounded-xl bg-emerald-500/15 flex items-center justify-center text-emerald-400">
          <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><rect x="1" y="4" width="22" height="16" rx="2"/><line x1="1" y1="10" x2="23" y2="10"/></svg>
        </div>
        <div>
          <h1 className="text-2xl font-bold text-white mb-1">Payment</h1>
          <p className="text-slate-400 text-sm">Your purchases and enrolled courses</p>
        </div>
      </div>

      {loading ? (
        <div className="space-y-4 animate-pulse">
          {[1, 2, 3].map(i => (
            <div key={i} className="bg-[#111111] rounded-2xl p-6 border border-slate-800">
              <div className="h-5 bg-white/5 rounded w-1/3 mb-3" />
              <div className="h-4 bg-white/5 rounded w-1/2 mb-2" />
              <div className="h-4 bg-white/5 rounded w-1/4" />
            </div>
          ))}
        </div>
      ) : (
        <>
          {/* Enrolled Courses */}
          <div className="mb-8">
            <h2 className="text-lg font-bold text-white mb-4 flex items-center gap-2">
              <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"/><polyline points="22 4 12 14.01 9 11.01"/></svg>
              Enrolled Courses
            </h2>
            {enrollments.length === 0 ? (
              <div className="bg-[#111111] rounded-2xl p-8 border border-slate-800 text-center">
                <div className="w-14 h-14 rounded-2xl bg-blue-500/10 flex items-center justify-center text-blue-400 mx-auto mb-3">
                  <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M4 19.5v-15A2.5 2.5 0 0 1 6.5 2H20v20H6.5a2.5 2.5 0 0 1 0-5H20"/></svg>
                </div>
                <h3 className="text-white font-semibold mb-1">No Enrolled Courses</h3>
                <p className="text-slate-400 text-sm mb-4">Purchase a course to start learning.</p>
                <Link to="/basic/courses" className="inline-flex items-center gap-2 text-sm font-semibold text-green-brand hover:text-green-400 no-underline">
                  Browse Courses ΓåÆ
                </Link>
              </div>
            ) : (
              <div className="grid sm:grid-cols-2 gap-4">
                {enrollments.map((enrol, idx) => (
                  <motion.div
                    key={enrol.id}
                    initial={{ opacity: 0, y: 15 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ delay: idx * 0.05 }}
                  >
                    <Link
                      to={`/basic/courses/${enrol.courseId}`}
                      className="block bg-[#111111] rounded-2xl p-5 border border-slate-800 hover:border-green-brand/30 transition-all no-underline group"
                    >
                      <div className="flex items-start justify-between mb-3">
                        <div className="w-10 h-10 rounded-xl bg-green-brand/10 flex items-center justify-center text-green-brand">
                          <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><polygon points="5 3 19 12 5 21 5 3" /></svg>
                        </div>
                        <span className="text-xs font-semibold bg-emerald-500/15 text-emerald-400 px-2.5 py-1 rounded-full">Active</span>
                      </div>
                      <h3 className="text-white font-bold mb-1 group-hover:text-green-brand transition-colors">{enrol.courseTitle}</h3>
                      <div className="flex items-center gap-3 text-xs text-slate-500">
                        <span>{enrol.variant?.months || 'ΓÇö'}mo plan</span>
                        <span>ΓÇó</span>
                        <span>{formatCurrency(enrol.amount)}</span>
                        {enrol.expiresAt && (
                          <>
                            <span>ΓÇó</span>
                            <span>Expires {new Date(enrol.expiresAt).toLocaleDateString('en-IN', { month: 'short', year: 'numeric' })}</span>
                          </>
                        )}
                      </div>
                      <div className="mt-3 pt-3 border-t border-white/5 text-xs text-green-brand font-semibold group-hover:translate-x-1 transition-transform">
                        Continue Learning ΓåÆ
                      </div>
                    </Link>
                  </motion.div>
                ))}
              </div>
            )}
          </div>

          {/* Payment History */}
          <div>
            <h2 className="text-lg font-bold text-white mb-4 flex items-center gap-2">
              <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M4 2v20l4-2 4 2 4-2 4 2V2l-4 2-4-2-4 2-4-2z"/><path d="M8 10h8"/><path d="M8 14h5"/></svg>
              Payment History
            </h2>
            {payments.length === 0 ? (
              <div className="bg-[#111111] rounded-2xl p-8 border border-slate-800 text-center">
                <p className="text-slate-400 text-sm">No payments found.</p>
              </div>
            ) : (
              <div className="space-y-3">
                {payments.map((pay, idx) => (
                  <motion.div
                    key={pay.id}
                    initial={{ opacity: 0, x: -10 }}
                    animate={{ opacity: 1, x: 0 }}
                    transition={{ delay: idx * 0.04 }}
                    className="bg-[#111111] rounded-2xl p-5 border border-slate-800"
                  >
                    <div className="flex items-start justify-between mb-2">
                      <div>
                        <h4 className="text-white font-semibold text-sm">{pay.courseTitle || 'Course Purchase'}</h4>
                        <p className="text-xs text-slate-500 mt-0.5">{pay.variantLabel || `${pay.variantMonths || 'ΓÇö'}mo plan`}</p>
                      </div>
                      {statusBadge(pay.status)}
                    </div>
                    <div className="flex items-center gap-4 text-xs text-slate-400">
                      <span className="font-semibold text-white">{formatCurrency(pay.amount)}</span>
                      <span>{formatDate(pay.createdAt)}</span>
                      {pay.orderId && (
                        <span className="font-mono text-[10px] text-slate-500">#{pay.orderId.slice(-8)}</span>
                      )}
                      {pay.paymentId && (
                        <span className="font-mono text-[10px] text-slate-500">
                          Pay: {pay.paymentId.slice(-8)}
                        </span>
                      )}
                    </div>
                  </motion.div>
                ))}
              </div>
            )}
          </div>
        </>
      )}
    </div>
  );
}

import { useState, useEffect } from 'react'
import { ListSkeleton } from '../../components/ui/Skeleton'
import { useAuth } from '../../context/AuthContext'
import { getCollectionWhere } from '../../lib/firebaseHelpers'
import CounsellingForm from '../../components/CounsellingForm'
import { CalendarIcon, ClockIcon, UsersIcon, VideoIcon } from '../../components/Icons'

const HeadsetIcon = ({ size = 18, className = '' }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className}>
    <path d="M3 18v-6a9 9 0 0 1 18 0v6" /><path d="M21 19a2 2 0 0 1-2 2h-1a2 2 0 0 1-2-2v-3a2 2 0 0 1 2-2h3zM3 19a2 2 0 0 0 2 2h1a2 2 0 0 0 2-2v-3a2 2 0 0 0-2-2H3z" />
  </svg>
)

export default function StudentCounselling() {
  const { user } = useAuth()
  const [bookings, setBookings] = useState([])
  const [loading, setLoading] = useState(true)
  const [showForm, setShowForm] = useState(false)

  useEffect(() => { if (user) loadBookings() }, [user])

  const loadBookings = async () => {
    setLoading(true)
    try {
      const all = await getCollectionWhere('counsellingBookings', 'studentName', '==', user.name || '')
      setBookings(all)
    } catch (err) { console.error(err) }
    finally { setLoading(false) }
  }

  const statusColors = { pending: 'badge-gold', approved: 'badge-green', completed: 'badge-navy', rejected: 'badge-red' }

  return (
    <div>
      <div className="flex items-center justify-between mb-6">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-xl bg-teal-500/15 flex items-center justify-center text-teal-400">
            <HeadsetIcon size={20} />
          </div>
          <div>
            <h1 className="text-2xl font-bold text-white mb-1">Counselling Room</h1>
            <p className="text-slate-400 text-sm">Book and manage your counselling sessions</p>
          </div>
        </div>
        <button onClick={() => setShowForm(!showForm)} className="btn-primary">
          {showForm ? 'Close' : '+ Book Session'}
        </button>
      </div>

      {showForm && (
        <div className="bg-[#111111] rounded-2xl p-6 border border-slate-800 mb-6">
          <h3 className="text-lg font-bold text-white mb-4">New Booking</h3>
          <CounsellingForm compact onSuccess={() => { setShowForm(false); loadBookings() }} />
        </div>
      )}

      <div className="mb-8">
        <h2 className="text-lg font-bold text-white mb-4">Your Sessions</h2>
        {loading ? (
          <div className="py-8"><ListSkeleton count={3} /></div>
        ) : bookings.length === 0 ? (
          <div className="bg-[#111111] rounded-2xl p-8 border border-slate-800 text-center">
            <HeadsetIcon size={32} className="text-slate-600 mx-auto mb-3" />
            <p className="text-slate-400 mb-2">No counselling sessions yet</p>
            <p className="text-sm text-slate-500">Book your first session to get started</p>
          </div>
        ) : (
          <div className="space-y-4">
            {bookings.map(b => (
              <div key={b.id} className="bg-[#111111] rounded-2xl p-5 border border-slate-800 hover:border-teal-500/20 transition-all">
                <div className="flex items-start justify-between mb-3">
                  <div>
                    <h3 className="font-bold text-white">{b.topic}</h3>
                    <p className="text-xs text-slate-500">{b.studentName} {b.parentName ? `& ${b.parentName}` : ''}</p>
                  </div>
                  <span className={`badge ${statusColors[b.status] || 'badge-navy'}`}>{b.status}</span>
                </div>
                <div className="flex items-center gap-4 text-sm text-slate-400">
                  <span className="inline-flex items-center gap-1.5"><CalendarIcon size={14} className="text-slate-500" /> {b.preferredDate}</span>
                  <span className="inline-flex items-center gap-1.5"><ClockIcon size={14} className="text-slate-500" /> {b.preferredTime}</span>
                </div>
                {b.meetingLink && b.status === 'approved' && (
                  <a href={b.meetingLink} target="_blank" rel="noopener noreferrer" className="btn-primary mt-3 text-sm no-underline inline-flex items-center gap-2">
                    <VideoIcon size={16} /> Join Meeting
                  </a>
                )}
              </div>
            ))}
          </div>
        )}
      </div>

      <div className="bg-gradient-to-br from-green-brand to-green-dark rounded-2xl p-6 text-white">
        <h3 className="font-bold mb-2 flex items-center gap-2"><HeadsetIcon size={18} /> About Counselling</h3>
        <p className="text-sm text-white/90 mb-3">Our counselling sessions are conducted via Google Meet. Both student and parent can join.</p>
        <ul className="text-sm text-white/80 space-y-1.5">
          <li className="flex items-center gap-2"><span className="w-1.5 h-1.5 rounded-full bg-white/60" /> Sessions are 30-45 minutes long</li>
          <li className="flex items-center gap-2"><span className="w-1.5 h-1.5 rounded-full bg-white/60" /> Available Mon-Sat, 9AM-8PM</li>
          <li className="flex items-center gap-2"><span className="w-1.5 h-1.5 rounded-full bg-white/60" /> Free for enrolled students</li>
        </ul>
      </div>
    </div>
  )
}

import { useState, useEffect } from 'react'
import { ListSkeleton } from '../../components/ui/Skeleton'
import { useAuth } from '../../context/AuthContext'
import { getCollectionWhere } from '../../lib/firebaseHelpers'
import DoubtForm from '../../components/DoubtForm'
import { MessageSquareIcon, ClockIcon, CheckCircleIcon } from '../../components/Icons'

export default function StudentDoubts() {
  const { user } = useAuth()
  const [doubts, setDoubts] = useState([])
  const [loading, setLoading] = useState(true)
  const [showForm, setShowForm] = useState(false)

  useEffect(() => { if (user) loadDoubts() }, [user])

  const loadDoubts = async () => {
    setLoading(true)
    try {
      const all = await getCollectionWhere('doubts', 'studentUid', '==', user.uid || user.id || '')
      setDoubts(all)
    } catch (err) { console.error(err) }
    finally { setLoading(false) }
  }

  const statusColors = { pending: 'badge-gold', answered: 'badge-green' }

  return (
    <div>
      <div className="flex items-center justify-between mb-6">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-xl bg-blue-500/15 flex items-center justify-center text-blue-400">
            <MessageSquareIcon size={20} />
          </div>
          <div>
            <h1 className="text-2xl font-bold text-white mb-1">My Doubts</h1>
            <p className="text-slate-400 text-sm">Ask questions with text or photo</p>
          </div>
        </div>
        <button onClick={() => setShowForm(!showForm)} className="btn-primary">
          {showForm ? 'Close' : '+ Ask Doubt'}
        </button>
      </div>

      {showForm && (
        <div className="bg-[#111111] rounded-2xl p-6 border border-slate-800 mb-6">
          <h3 className="text-lg font-bold text-white mb-4">New Doubt</h3>
          <DoubtForm onSuccess={() => { setShowForm(false); loadDoubts() }} />
        </div>
      )}

      <h2 className="text-lg font-bold text-white mb-4 flex items-center gap-2">
        <ClockIcon size={18} className="text-slate-500" /> Your Doubts
      </h2>
      {loading ? (
        <div className="py-8"><ListSkeleton count={4} /></div>
      ) : doubts.length === 0 ? (
        <div className="bg-[#111111] rounded-2xl p-8 border border-slate-800 text-center">
          <MessageSquareIcon size={32} className="text-slate-600 mx-auto mb-3" />
          <p className="text-slate-400 mb-2">No doubts yet</p>
          <p className="text-sm text-slate-500">Click "+ Ask Doubt" to get started</p>
        </div>
      ) : (
        <div className="space-y-4">
          {doubts.map(d => (
            <div key={d.id} className="bg-[#111111] rounded-2xl p-5 border border-slate-800 hover:border-blue-500/20 transition-all">
              <div className="flex items-start justify-between mb-3">
                <div className="flex items-center gap-2">
                  {d.subject && <span className="badge badge-navy text-xs">{d.subject}</span>}
                  <span className={`badge ${statusColors[d.status] || 'badge-navy'} inline-flex items-center gap-1`}>
                    {d.status === 'answered' && <CheckCircleIcon size={12} />}
                    {d.status}
                  </span>
                </div>
              </div>
              {d.text && <p className="text-sm text-slate-300 mb-3">{d.text}</p>}
              {d.imageUrl && (
                <a href={d.imageUrl} target="_blank" rel="noopener" className="block mb-3">
                  <img src={d.imageUrl} alt="Doubt" className="w-full max-h-48 object-contain rounded-lg border border-slate-700" loading="lazy" />
                </a>
              )}
              {d.adminReply && (
                <div className="mt-3 p-3 rounded-xl bg-green-brand/5 border border-green-brand/20">
                  <p className="text-xs font-bold text-green-brand uppercase mb-1 flex items-center gap-1.5">
                    <CheckCircleIcon size={12} /> Admin Reply
                  </p>
                  <p className="text-sm text-slate-300">{d.adminReply}</p>
                </div>
              )}
            </div>
          ))}
        </div>
      )}
    </div>
  )
}

import { useState, useEffect } from 'react'
import { useAuth } from '../../context/AuthContext'
import { collection, query, where, getDocs } from 'firebase/firestore'
import { db } from '../../lib/firebase'
import Modal from '../../components/Modal'
import { TrophyIcon, CheckCircleIcon } from '../../components/Icons'
import { ListSkeleton } from '../../components/ui/Skeleton'

export default function StudentMockResults() {
  const { user } = useAuth()
  const [attempts, setAttempts] = useState([])
  const [loading, setLoading] = useState(true)
  const [selected, setSelected] = useState(null) // selected attempt with full breakdown
  const [questions, setQuestions] = useState([]) // loaded questions for selected test

  useEffect(() => {
    if (!user) return
    let alive = true
    const load = async () => {
      try {
        // No orderBy ΓåÆ avoids needing a composite index for (uid + submittedAt).
        // Sort client-side by submittedAt desc.
        const q = query(collection(db, 'mockAttempts'), where('uid', '==', user.uid))
        const snap = await getDocs(q)
        if (!alive) return
        const data = snap.docs
          .map(d => ({ id: d.id, ...d.data() }))
          .sort((a, b) => {
            const ta = a.submittedAt?.toMillis?.() ?? new Date(a.submittedAt || 0).getTime()
            const tb = b.submittedAt?.toMillis?.() ?? new Date(b.submittedAt || 0).getTime()
            return tb - ta
          })
        setAttempts(data)
      } catch (err) {
        console.error('[StudentMockResults]', err)
      } finally { if (alive) setLoading(false) }
    }
    load()
    return () => { alive = false }
  }, [user])

  const loadQuestions = async (attempt) => {
    setSelected(attempt)
    try {
      const snap = await getDocs(collection(db, 'mockTests'))
      const test = snap.docs.map(d => ({ id: d.id, ...d.data() })).find(t => t.id === attempt.testId)
      if (test?.questions) {
        setQuestions(test.questions)
      } else {
        setQuestions([])
      }
    } catch { setQuestions([]) }
  }

  const statusColors = {
    completed: 'badge-green',
    'auto-submitted-timeout': 'badge-gold',
    'auto-submitted-cheating': 'badge-red',
  }

  return (
    <div>
      <div className="flex items-center gap-3 mb-6">
        <div className="w-10 h-10 rounded-xl bg-green-brand/15 flex items-center justify-center text-green-brand">
          <TrophyIcon size={20} />
        </div>
        <div>
          <h1 className="text-2xl font-bold text-white mb-1">My Results</h1>
          <p className="text-slate-400 text-sm">All mock test attempts with detailed answers</p>
        </div>
      </div>

      {loading ? (
        <div className="py-8"><ListSkeleton count={4} /></div>
      ) : attempts.length === 0 ? (
        <div className="bg-[#111111] rounded-2xl p-8 border border-slate-800 text-center">
          <TrophyIcon size={32} className="text-slate-600 mx-auto mb-3" />
          <p className="text-slate-400 mb-2">No test attempts yet</p>
          <p className="text-sm text-slate-500">Take a mock test to see your results here</p>
        </div>
      ) : (
        <div className="space-y-4">
          {attempts.map(a => (
            <div key={a.id} className="bg-[#111111] rounded-2xl p-5 border border-slate-800 hover:border-green-brand/20 transition-all">
              <div className="flex items-start justify-between mb-3">
                <div>
                  <h3 className="font-bold text-white">{a.testTitle || 'Mock Test'}</h3>
                  <p className="text-xs text-slate-500 mt-1">{a.category} ΓÇó {a.submittedAt ? new Date(a.submittedAt?.toDate?.() || a.submittedAt).toLocaleDateString('en-IN') : ''}</p>
                </div>
                <span className={`badge ${statusColors[a.status] || 'badge-navy'}`}>{a.status?.replace('auto-submitted-', '')}</span>
              </div>
              <div className="grid grid-cols-4 gap-3 mb-3">
                <div className="bg-green-brand/5 rounded-xl p-2.5 text-center">
                  <p className="text-lg font-bold text-green-brand">{a.correct}</p>
                  <p className="text-[10px] text-slate-400 uppercase">Correct</p>
                </div>
                <div className="bg-red-500/5 rounded-xl p-2.5 text-center">
                  <p className="text-lg font-bold text-red-400">{a.wrong}</p>
                  <p className="text-[10px] text-slate-400 uppercase">Wrong</p>
                </div>
                <div className="bg-slate-500/5 rounded-xl p-2.5 text-center">
                  <p className="text-lg font-bold text-slate-400">{a.unattempted}</p>
                  <p className="text-[10px] text-slate-400 uppercase">Skipped</p>
                </div>
                <div className="bg-blue-500/5 rounded-xl p-2.5 text-center">
                  <p className="text-lg font-bold text-blue-400">{a.percentage?.toFixed(1)}%</p>
                  <p className="text-[10px] text-slate-400 uppercase">Score</p>
                </div>
              </div>
              <div className="flex items-center justify-between">
                <p className="text-sm text-slate-400">{a.score}/{a.maxMarks} marks</p>
                <button onClick={() => loadQuestions(a)} className="text-sm text-green-brand font-bold cursor-pointer hover:underline">
                  View Full Results
                </button>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* Full Results Modal */}
      <Modal isOpen={!!selected} onClose={() => { setSelected(null); setQuestions([]) }} title={`${selected?.testTitle || 'Test'} ΓÇö Full Results`} size="lg">
        {selected && (
          <div className="space-y-4 max-h-[70vh] overflow-y-auto pr-2">
            {/* Summary */}
            <div className="grid grid-cols-4 gap-3 p-4 bg-white/5 rounded-xl">
              <div className="text-center"><p className="text-xl font-bold text-green-brand">{selected.correct}</p><p className="text-xs text-slate-400">Correct</p></div>
              <div className="text-center"><p className="text-xl font-bold text-red-400">{selected.wrong}</p><p className="text-xs text-slate-400">Wrong</p></div>
              <div className="text-center"><p className="text-xl font-bold text-slate-400">{selected.unattempted}</p><p className="text-xs text-slate-400">Skipped</p></div>
              <div className="text-center"><p className="text-xl font-bold text-blue-400">{selected.score}/{selected.maxMarks}</p><p className="text-xs text-slate-400">Score</p></div>
            </div>

            {/* Question by Question */}
            {questions.length > 0 ? questions.map((q, idx) => {
              const bk = selected.breakdown?.find(b => b.qid === q.id)
              const userAnswer = bk?.selectedIndex !== undefined ? bk.selectedIndex : null
              const isCorrect = bk?.status === 'correct'
              const isSkipped = !bk || bk.status === 'skipped'

              return (
                <div key={q.id || idx} className={`rounded-xl p-4 border ${isCorrect ? 'bg-green-brand/5 border-green-brand/20' : isSkipped ? 'bg-white/5 border-slate-700' : 'bg-red-500/5 border-red-500/20'}`}>
                  <div className="flex items-start gap-3 mb-3">
                    <span className={`w-7 h-7 rounded-full flex items-center justify-center text-xs font-bold shrink-0 ${isCorrect ? 'bg-green-brand/20 text-green-brand' : isSkipped ? 'bg-slate-500/20 text-slate-400' : 'bg-red-500/20 text-red-400'}`}>
                      {isCorrect ? 'Γ£ô' : isSkipped ? 'ΓÇö' : 'Γ£ù'}
                    </span>
                    <div className="flex-1">
                      <p className="text-sm text-white font-medium">Q{idx + 1}. {q.question}</p>
                      {q.imageUrl && (
                        <img src={q.imageUrl} alt="" className="mt-2 max-h-48 rounded border border-slate-700" loading="lazy" />
                      )}
                    </div>
                  </div>
                  <div className="ml-10 space-y-1.5">
                    {q.options?.map((opt, oi) => {
                      const isUserPick = userAnswer === oi
                      const isRight = q.correctIndex === oi
                      let cls = 'text-slate-400'
                      if (isRight) cls = 'text-green-brand font-medium'
                      else if (isUserPick && !isRight) cls = 'text-red-400 line-through'
                      return (
                        <div key={oi} className={`flex items-center gap-2 text-sm ${cls}`}>
                          <span className={`w-5 h-5 rounded-full flex items-center justify-center text-[10px] font-bold ${isRight ? 'bg-green-brand/20 text-green-brand' : isUserPick ? 'bg-red-500/20 text-red-400' : 'bg-white/5 text-slate-500'}`}>
                            {String.fromCharCode(65 + oi)}
                          </span>
                          <span>{opt}</span>
                          {isRight && <span className="text-[10px] text-green-brand font-bold">(Correct)</span>}
                          {isUserPick && !isRight && <span className="text-[10px] text-red-400 font-bold">(Your answer)</span>}
                        </div>
                      )
                    })}
                    {q.explanation && (
                      <div className="mt-2 p-2 rounded-lg bg-blue-500/5 border border-blue-500/10">
                        <p className="text-xs font-bold text-blue-400 uppercase mb-1">Explanation</p>
                        <p className="text-xs text-slate-300">{q.explanation}</p>
                      </div>
                    )}
                    {selected.adminRemarks?.[q.id] && (
                      <div className="mt-2 p-2 rounded-lg bg-amber-500/10 border border-amber-500/30">
                        <p className="text-xs font-bold text-amber-400 uppercase mb-1 flex items-center gap-1">≡ƒÆ¼ Teacher's Remark</p>
                        <p className="text-xs text-amber-100">{selected.adminRemarks[q.id]}</p>
                      </div>
                    )}
                  </div>
                </div>
              )
            }) : (
              <p className="text-slate-500 text-center py-4">Question details not available for this attempt.</p>
            )}
          </div>
        )}
      </Modal>
    </div>
  )
}
